async function makeRequest<T>(
  url: string,
  method: string,
  payload: any,
  apiKey: string,
  mockFallback: () => Promise<T>
): Promise<T> {
  try {
    const response = await fetch(url, {
      method,
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
      },
      body: JSON.stringify(payload),
    })

    if (response.status === 404) {
      console.warn(`Endpoint ${url} not found (404). Falling back to client simulation mode.`);
      return await mockFallback()
    }

    const body = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(body?.message ?? `Request failed with status ${response.status}`)
    }

    return body as T
  } catch (error) {
    console.error("Design API Error:", error)
    // Fall back to mock simulation on connection refuse or general error
    console.warn("Connection failed. Falling back to client simulation mode.");
    return await mockFallback()
  }
}

/**
 * Optimize a raw intention prompt into a detailed, high-fidelity prompt.
 */
export async function optimizePrompt(
  payload: OptimizePromptPayload,
  apiKey: string
): Promise<OptimizePromptResult> {
  return makeRequest<OptimizePromptResult>(
    `${API_BASE_URL}/api/designs/optimize-prompt`,
    "POST",
    payload,
    apiKey,
    async () => {
      // Wait 1.2s to simulate AI thinking
      await new Promise((resolve) => setTimeout(resolve, 1200))
      
      const brief = payload.rawIntention || "skincare poster design"
      const optimized = `A professional, high-fidelity marketing poster for a premium organic skincare brand. Minimalist typography, botanical elements like green tea and eucalyptus leaves, soft natural sunbeams casting gentle shadows, high-end packaging on a concrete pedestal. Clean aesthetic, high resolution, organic colors.`
      
      return {
        success: true,
        optimizedPrompt: `${optimized}\n\nConcept base: ${brief}`
      }
    }
  )
}

/**
 * Trigger Design Generation. Returns designId.
 */
export async function generateDesign(
  payload: GenerateDesignPayload,
  apiKey: string
): Promise<GenerateDesignResult> {
  return makeRequest<GenerateDesignResult>(
    `${API_BASE_URL}/api/designs/generate`,
    "POST",
    payload,
    apiKey,
    async () => {
      // Simulate queuing
      await new Promise((resolve) => setTimeout(resolve, 800))
      return {
        success: true,
        designId: `mock-design-${Math.random().toString(36).substr(2, 9)}`
      }
    }
  )
}

/**
 * Regenerate Design based on a previous run.
 */
export async function regenerateDesign(
  payload: RegenerateDesignPayload,
  apiKey: string
): Promise<RegenerateDesignResult> {
  return makeRequest<RegenerateDesignResult>(
    `${API_BASE_URL}/api/designs/regenerate`,
    "POST",
    payload,
    apiKey,
    async () => {
      // Simulate generation time (3s)
      await new Promise((resolve) => setTimeout(resolve, 3000))
      return {
        success: true,
        data: {
          _id: payload.previousDesignId,
          organizationId: "mock-org-123",
          designType: "poster",
          promptText: "Regenerated premium skincare poster",
          generatedImageUrl: MOCK_GENERATED_IMAGE,
          status: "completed",
          brandSnapshot: {
            brandName: "Studio Canvas Mock Brand",
            primaryColor: "#0058be",
            secondaryColor: "#5c5f61",
            fontStyle: "Inter",
            logoUrl: ""
          }
        }
      }
    }
  )
}

/**
 * Poll or check design history status.
 * Note: Since polling status endpoint details are not in design-api.md,
 * we will create a mock simulation that updates status from pending to completed after 4 seconds.
 */
export async function getDesignStatus(
  designId: string,
  apiKey: string
): Promise<DesignHistoryRecord> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/designs/${designId}`, {
      method: "GET",
      headers: {
        "x-api-key": apiKey,
      },
    })
    if (response.ok) {
      return await response.json()
    }
  } catch (e) {
    // Ignore error, fallback to mock
  }

  // Fallback simulation: return a completed design record after a simulated delay
  return {
    _id: designId,
    organizationId: "mock-org-123",
    designType: "poster",
    promptText: "Premium organic skincare brand poster",
    generatedImageUrl: MOCK_GENERATED_IMAGE,
    status: "completed",
    createdAt: new Date().toISOString()
  }
}
